// Fusionner toutes les données pour construire la question au chatbot
let stats = {};
let kpis = {};
let comparison = {};

try { stats = $('GET Stats Tickets').first().json || {}; } catch(e) {}
try { kpis = $("GET KPIs Aujourd'hui").first().json || {}; } catch(e) {}
try { comparison = $('GET Comparaison 7j').first().json || {}; } catch(e) {}

const today = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Construire une question riche pour Gemma 4 avec les données réelles
const question = `En tant que superviseur, génère-moi un résumé professionnel et détaillé de l'activité d'aujourd'hui (${today}) pour la plateforme AutoAssist de gestion des réclamations pièces automobiles. Voici les données réelles :

Statistiques tickets du jour :
- Nouveaux tickets: ${stats.nouveau || 0}
- En cours de traitement: ${stats.enCours || 0}
- Résolus: ${stats.resolu || 0}
- Fermés: ${stats.ferme || 0}
- Total: ${stats.total || 0}

KPIs :
- Taux de résolution: ${kpis.tauxResolution || 'N/A'}%
- Temps moyen de résolution: ${kpis.tempsMoyenMinutes || 'N/A'} minutes
- Total tickets période: ${kpis.totalTickets || 'N/A'}

Comparaison vs semaine précédente :
- Delta tickets: ${comparison.deltaTickets || 'N/A'}%
- Delta résolution: ${comparison.deltaResolution || 'N/A'}%

Rédige un résumé en français avec des recommandations concrètes pour le superviseur. Utilise des emojis pour rendre le rapport lisible. Mentionne les points forts et les points d'attention.`;

return [{ json: { question, group_name: 'n8n-daily-report', today, stats, kpis } }];

const gemmaResponse = $('Appel Gemma 4 (RAG)').first().json;
const questionData = $('Construire Question IA').first().json;
const today = questionData.today;
const stats = questionData.stats || {};
const kpis = questionData.kpis || {};

// Récupérer la réponse de Gemma 4
let aiSummary = '';
let llmUsed = 'N/A';
let responseTime = 'N/A';

if (gemmaResponse && gemmaResponse.answer) {
  aiSummary = gemmaResponse.answer;
  llmUsed = gemmaResponse.llm_used || 'gemma4';
  responseTime = gemmaResponse.response_time_ms ? `${(gemmaResponse.response_time_ms / 1000).toFixed(1)}s` : 'N/A';
} else {
  aiSummary = '⚠️ Le résumé IA n\'a pas pu être généré. Voici les données brutes ci-dessous.';
}

// Convertir les sauts de ligne markdown en HTML
const aiHtml = aiSummary
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.*?)\*/g, '<em>$1</em>')
  .replace(/\n/g, '<br>');

const html = `
<div style="font-family:'Segoe UI',Arial,sans-serif;max-width:650px;margin:0 auto;">
  <div style="background:linear-gradient(135deg,#00695C,#00897B);color:white;padding:25px;border-radius:12px 12px 0 0;text-align:center;">
    <h1 style="margin:0;">🧠 Résumé IA — AutoAssist</h1>
    <p style="margin:5px 0 0;opacity:0.9;">${today}</p>
    <p style="margin:3px 0 0;opacity:0.7;font-size:12px;">Généré par ${llmUsed} en ${responseTime}</p>
  </div>

  <div style="background:white;padding:25px;border:1px solid #e0e0e0;">
    <div style="background:#E0F2F1;border-left:4px solid #00897B;padding:15px;margin-bottom:20px;border-radius:0 8px 8px 0;">
      <h3 style="margin:0 0 8px;color:#00695C;">🤖 Analyse par Intelligence Artificielle</h3>
      <div style="line-height:1.6;color:#333;">${aiHtml}</div>
    </div>

    <h3 style="color:#333;">📊 Données brutes du jour</h3>
    <table style="width:100%;border-collapse:collapse;margin-top:10px;">
      <tr style="background:#E0F2F1;">
        <td style="padding:10px;"><strong>🆕 Nouveaux</strong></td>
        <td style="padding:10px;text-align:right;font-weight:700;color:#1565C0;">${stats.nouveau || 0}</td>
        <td style="padding:10px;"><strong>⏳ En cours</strong></td>
        <td style="padding:10px;text-align:right;font-weight:700;color:#F57C00;">${stats.enCours || 0}</td>
      </tr>
      <tr>
        <td style="padding:10px;"><strong>✅ Résolus</strong></td>
        <td style="padding:10px;text-align:right;font-weight:700;color:#2E7D32;">${stats.resolu || 0}</td>
        <td style="padding:10px;"><strong>🔒 Fermés</strong></td>
        <td style="padding:10px;text-align:right;font-weight:700;color:#757575;">${stats.ferme || 0}</td>
      </tr>
      <tr style="background:#E0F2F1;">
        <td style="padding:10px;"><strong>📈 Total</strong></td>
        <td style="padding:10px;text-align:right;font-weight:700;font-size:18px;">${stats.total || 0}</td>
        <td style="padding:10px;"><strong>📊 Résolution</strong></td>
        <td style="padding:10px;text-align:right;font-weight:700;color:#00695C;">${kpis.tauxResolution || 'N/A'}%</td>
      </tr>
    </table>
  </div>

  <div style="background:#f8f9fa;padding:15px;border-radius:0 0 12px 12px;text-align:center;">
    <a href="http://localhost:3000/dashboard" style="color:#00897B;font-weight:700;">Ouvrir le Dashboard →</a>
    <p style="color:#888;font-size:11px;margin:8px 0 0;">© 2026 AutoAssist — Résumé IA quotidien via n8n + Gemma 4</p>
  </div>
</div>`;

return [{ json: { html, subject: `🧠 Résumé IA AutoAssist — ${today}` } }];
